function PromoBanner() {
  // Server picks blue; client picks green
  const color = ['#2563eb', '#16a34a', '#9333ea'][Math.floor(Math.random() * 3)];
  return <div style={{ background: color }}>Sale!</div>;
}

function Timestamp() {
  // Server renders 2026-09-26, client re-renders with actual local time
  return (
    <time suppressHydrationWarning datetime={new Date().toISOString()}>
      {new Date().toLocaleString()}
    </time>
  );
}

function ThemeToggle() {
  const [theme, setTheme] = useState('system');

  useEffect(() => {
    // This runs only on the client, after hydration completes
    const saved = localStorage.getItem('theme') ?? 'system';
    setTheme(saved);
  }, []);

  return <button onClick={() => toggleTheme(theme)}>Toggle theme</button>;
}
